import { test } from "node:test";
import assert from "node:assert/strict";
import { Logger } from "../src/logging/logger.ts";
import { redact } from "../src/logging/redact.ts";
import { bookAppointment, type Appointment, type Patient } from "../src/scheduling/appointments.ts";
import { sendReminders } from "../src/scheduling/reminders.ts";

function capture() {
    const lines: string[] = [];
    const log = new Logger({ write: (l) => lines.push(l) }, () => new Date("2026-11-19T08:00:00Z"), { service: "scheduling" });
    return { lines, log, entries: () => lines.map((l) => JSON.parse(l)) };
}

const patient = (n: number): Patient => ({
    id: `p${n}`,
    name: `Patient ${n}`,
    dateOfBirth: `1980-01-0${n}`,
    phone: `+1555010${n}`,
    email: `patient${n}@mail.example`,
    insuranceId: `INS-77${n}`,
});

const appt: Appointment = { id: "a1", patientId: "p1", clinicId: "c9", startsAt: "2026-11-20T09:30:00Z", reason: { code: "Z00.0", notes: "chest pain since Monday" } };

// Anything a patient could be identified or contacted by.
const SECRETS = [/\+1555010\d/, /1980-01-0\d/, /patient\d@mail\.example/, /INS-77\d/, /chest pain/];
const leaks = (lines: string[]) => lines.flatMap((l) => SECRETS.filter((re) => re.test(l)).map((re) => re.source));

test("sensitive fields are redacted whatever their casing", () => {
    assert.deepEqual(redact({ SSN: "123-45-6789", date_of_birth: "1990-02-03", Email: "a@b.io", clinicId: "c1" }), {
        SSN: "[redacted]",
        date_of_birth: "[redacted]",
        Email: "[redacted]",
        clinicId: "c1",
    });
});

test("booking an appointment logs ids but no patient details", async () => {
    const { lines, entries, log } = capture();
    const store = { isSlotFree: async () => true, insert: async () => {} };
    assert.equal(await bookAppointment(store, log, patient(1), appt), true);
    assert.deepEqual(leaks(lines), []);
    const [entry] = entries();
    assert.deepEqual([entry.msg, entry.appointmentId, entry.clinicId, entry.patient.id], ["appointment booked", "a1", "c9", "p1"]);
});

test("email addresses typed into messages and errors are masked", () => {
    const { entries, log } = capture();
    log.error("could not notify jane.doe@clinic.example", { err: new Error("bounce from jane.doe@clinic.example") });
    const [entry] = entries();
    assert.equal(entry.msg, "could not notify [email]");
    assert.deepEqual(entry.err, { name: "Error", message: "bounce from [email]" });
});

test("records inside lists are redacted too", () => {
    const out = redact({ patients: [patient(1), patient(2)], phones: ["+15550101"] }) as { patients: Patient[] };
    console.log("redacted list:", JSON.stringify(out));
    assert.deepEqual(out.patients.map((p) => [p.id, p.phone, p.dateOfBirth]), [["p1", "[redacted]", "[redacted]"], ["p2", "[redacted]", "[redacted]"]]);
});

test("a reminder delivery failure is logged without any patient's phone number or birth date", async () => {
    const { lines, entries, log } = capture();
    const reminders = [1, 2, 3].map((n) => ({ appointmentId: `a${n}`, startsAt: "2026-11-20T09:30:00Z", patient: patient(n) }));
    const sent = await sendReminders({ sendBulk: async () => ["+15550102", "+15550103"] }, log, "c9", reminders);
    assert.equal(sent, 1);
    assert.deepEqual(leaks(lines), []);
    assert.deepEqual(entries()[0].failed.map((f: { appointmentId: string }) => f.appointmentId), ["a2", "a3"]);
});

test("redacting never modifies the object being logged", () => {
    const { log } = capture();
    const p = patient(4);
    const record = { patient: p, visits: [{ notes: "follow-up" }] };
    log.info("audit", record);
    assert.equal(p.phone, "+15550104");
    assert.equal(record.visits[0].notes, "follow-up");
});

test("a taken slot is logged with the time but not the patient's contact details", async () => {
    const { lines, entries, log } = capture();
    const store = { isSlotFree: async () => false, insert: async () => assert.fail("must not insert") };
    assert.equal(await bookAppointment(store, log, patient(5), appt), false);
    assert.deepEqual(leaks(lines), []);
    assert.equal(entries()[0].startsAt, "2026-11-20T09:30:00Z");
});
